 @Override public void onCreate(Bundle b){super.onCreate(b);V4Theme.apply(this);primary=V4Theme.primary(this);ScrollView s=new ScrollView(this);s.setBackgroundColor(ModernUi.screenBackground(this));root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(16),dp(14),dp(16),dp(26));root.setLayoutDirection(ar()?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);s.addView(root);LinearLayout hero=new LinearLayout(this);hero.setOrientation(LinearLayout.VERTICAL);hero.setPadding(dp(18),dp(16),dp(18),dp(17));hero.setBackground(bg(primary,26));TextView h=t(tr("قواعد Smart Reminder","Smart Reminder rules"),26,true);h.setTextColor(Color.WHITE);hero.addView(h);TextView sub=t(tr("حدد القواعد أو دع التطبيق يتعلم اختياراتك محليًا على جهازك.","Set rules or let the app learn your choices locally on your device."),12,false);sub.setTextColor(Color.rgb(224,239,236));hero.addView(sub);root.addView(hero,p(-1,-2,0,0,0,dp(12)));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(16),dp(14),dp(16),dp(16));card.setBackground(bg(ModernUi.surface(this),22));card.setElevation(dp(2));root.addView(card);Switch learn=new Switch(this);learn.setText(tr("تعلّم من اختياراتي محليًا","Learn from my choices on-device"));learn.setTextSize(14);learn.setTextColor(ModernUi.ink(this));learn.setChecked(SmartReminderRules.learningEnabled(this));card.addView(learn,new LinearLayout.LayoutParams(-1,dp(52)));learn.setOnCheckedChangeListener((b1,v)->SmartReminderRules.setLearningEnabled(this,v));TextView privacy=t(tr("لا تُرسل أنماطك أو اختياراتك إلى أي خادم.","Your reminder patterns are never sent to a server."),11,false);privacy.setTextColor(ModernUi.muted(this));card.addView(privacy);TextView l=t(tr("الفئة","Category"),13,true);l.setTextColor(ModernUi.ink(this));l.setPadding(0,dp(10),0,0);card.addView(l);category=new Spinner(this);category.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,Categories.labels(this,false)));card.addView(category,new LinearLayout.LayoutParams(-1,dp(52)));checks=new CheckBox[vals.length];GridLayout grid=new GridLayout(this);grid.setColumnCount(2);card.addView(grid);for(int i=0;i<vals.length;i++){CheckBox c=new CheckBox(this);c.setText(SmartReminderRules.label(this,vals[i]));c.setTextColor(ModernUi.ink(this));c.setPadding(dp(7),dp(5),dp(7),dp(5));checks[i]=c;GridLayout.LayoutParams gp=new GridLayout.LayoutParams();gp.width=0;gp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);grid.addView(c,gp);}Button save=b(tr("✓ حفظ القاعدة","✓ Save rule"),primary,Color.WHITE);card.addView(save,p(-1,dp(52),0,dp(12),0,0));Button reset=b(tr("إعادة الافتراضي لهذه الفئة","Reset category default"),ModernUi.surface(this),primary);card.addView(reset,p(-1,dp(48),0,dp(7),0,0));category.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){load();}public void onNothingSelected(AdapterView<?> p){}});save.setOnClickListener(v->{ArrayList<Integer>a=new ArrayList<>();for(int i=0;i<vals.length;i++)if(checks[i].isChecked())a.add(vals[i]);if(a.isEmpty()){Toast.makeText(this,tr("اختر تنبيهًا واحدًا على الأقل","Choose at least one reminder"),Toast.LENGTH_SHORT).show();return;}SmartReminderRules.set(this,Categories.CODES[category.getSelectedItemPosition()],a);Toast.makeText(this,tr("تم حفظ القاعدة","Rule saved"),Toast.LENGTH_SHORT).show();});reset.setOnClickListener(v->{SmartReminderRules.reset(this,Categories.CODES[category.getSelectedItemPosition()]);load();});setContentView(s);}
 private void load(){String code=Categories.CODES[category.getSelectedItemPosition()];HashSet<Integer> set=new HashSet<>();for(int x:SmartReminderRules.values(this,code))set.add(x);for(int i=0;i<vals.length;i++)checks[i].setChecked(set.contains(vals[i]));}
 private TextView t(String x,int z,boolean bold){TextView v=new TextView(this);v.setText(x);v.setTextSize(z);if(bold)v.setTypeface(null,1);return v;}private Button b(String x,int back,int text){Button v=new Button(this);v.setAllCaps(false);v.setText(x);v.setTextColor(text);v.setTextSize(14);v.setBackground(bg(back,15));return v;}private LinearLayout.LayoutParams p(int w,int h,int l,int tt,int r,int bb){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h);p.setMargins(l,tt,r,bb);return p;}
